def normalize_photo_emotion_key(value):
    """Normalize legacy/new emotion values into the six v159 choices or ''."""
    if isinstance(value, dict):
        value = value.get("key") or value.get("emotion") or value.get("label") or value.get("emoji")
    value = str(value or "").strip()
    aliases = {
        "cozy": "cozy", "ほっこり": "cozy", "ほっこりした": "cozy", "🥰": "cozy",
        "joy": "joy", "喜": "joy", "うれしい": "joy", "嬉しい": "joy", "😊": "joy",
        "surprise": "surprise", "びっくり": "surprise", "驚き": "surprise", "😲": "surprise",
        "anger": "anger", "怒": "anger", "おこった": "anger", "怒った": "anger", "😠": "anger",
        "sadness": "sadness", "sad": "sadness", "哀": "sadness", "かなしい": "sadness", "悲しい": "sadness", "😢": "sadness",
        "frustration": "frustration", "くやしい": "frustration", "悔しい": "frustration", "😣": "frustration",
        # v149-v158 compatibility: the former 楽/🎉 choice is folded into the
        # closest remaining positive choice instead of discarding old records.
        "fun": "joy", "楽": "joy", "🎉": "joy",
    }
    return aliases.get(value, "")


def normalize_parenting_tag_key(value):
    """Normalize parenting-mode values into one of the six parent-facing tags or ''."""
    if isinstance(value, dict):
        value = value.get("key") or value.get("tag") or value.get("label") or value.get("emoji")
    value = str(value or "").strip()
    aliases = {
        "effort": "effort", "がんばった": "effort", "頑張った": "effort", "⭐": "effort",
        "challenge": "challenge", "ちょうせん": "challenge", "挑戦": "challenge", "💪": "challenge",
        "discovery": "discovery", "はっけん": "discovery", "発見": "discovery", "💡": "discovery",
        "kindness": "kindness", "やさしさ": "kindness", "優しさ": "kindness", "❤️": "kindness", "❤": "kindness",
        "together": "together", "いっしょに": "together", "一緒に": "together", "🤝": "together",
        "tears": "tears", "なみだ": "tears", "涙": "tears", "😭": "tears",
    }
    return aliases.get(value, "")


def photo_parenting_tag_key(photo):
    reflection = (photo or {}).get("reflection_json") or {}
    if not isinstance(reflection, dict):
        return ""
    return normalize_parenting_tag_key(reflection.get("parenting_tag"))


def photo_parenting_tag_meta(photo_or_key):
    key = photo_or_key if isinstance(photo_or_key, str) else photo_parenting_tag_key(photo_or_key)
    key = normalize_parenting_tag_key(key)
    meta = dict(PARENTING_TAGS.get(key) or {})
    meta["key"] = key
    return meta


def parenting_tag_record(tag_key, source="parent_tap_cycle_v168"):
    tag_key = normalize_parenting_tag_key(tag_key)
    if not tag_key:
        return None
    meta = PARENTING_TAGS[tag_key]
    return {
        "key": tag_key,
        "label": meta["label"],
        "emoji": meta["emoji"],
        "color": meta["color"],
        "meaning": meta["meaning"],
        "updated_at": now_jst().isoformat(),
        "source": str(source or "parent_tap_cycle_v168"),
    }


def next_parenting_tag_key(current):
    current = normalize_parenting_tag_key(current)
    cycle = ("",) + PARENTING_TAG_ORDER
    try:
        index = cycle.index(current)
    except ValueError:
        index = 0
    return cycle[(index + 1) % len(cycle)]


def photo_emotion_key(photo):
    reflection = (photo or {}).get("reflection_json") or {}
    if not isinstance(reflection, dict):
        return ""
    return normalize_photo_emotion_key(reflection.get("emotion"))


def photo_emotion_meta(photo_or_key):
    key = photo_or_key if isinstance(photo_or_key, str) else photo_emotion_key(photo_or_key)
    key = normalize_photo_emotion_key(key)
    meta = dict(PHOTO_EMOTIONS.get(key) or {})
    meta["key"] = key
    return meta


ALL_PHOTO_TAG_ORDER = PHOTO_EMOTION_ORDER + PARENTING_TAG_ORDER


def photo_selected_tag_meta(photo):
    """Return the single visible tag across 通常 and こどもーど.

    v168 makes the two modes mutually exclusive. For legacy rows that still contain
    both fields, prefer the record with the newer updated_at timestamp; ties keep the
    normal feeling for backward compatibility.
    """
    reflection = (photo or {}).get("reflection_json") or {}
    if not isinstance(reflection, dict):
        reflection = {}
    emotion_record = reflection.get("emotion")
    parenting_record = reflection.get("parenting_tag")
    emotion_key = normalize_photo_emotion_key(emotion_record)
    parenting_key = normalize_parenting_tag_key(parenting_record)

    if emotion_key and parenting_key:
        emotion_at = str(emotion_record.get("updated_at") or "") if isinstance(emotion_record, dict) else ""
        parenting_at = str(parenting_record.get("updated_at") or "") if isinstance(parenting_record, dict) else ""
        if parenting_at and (not emotion_at or parenting_at > emotion_at):
            emotion_key = ""
        else:
            parenting_key = ""

    if emotion_key:
        meta = dict(PHOTO_EMOTIONS.get(emotion_key) or {})
        meta.update({"key": emotion_key, "mode": "normal"})
        return meta
    if parenting_key:
        meta = dict(PARENTING_TAGS.get(parenting_key) or {})
        meta.update({"key": parenting_key, "mode": "parenting"})
        return meta
    return {"key": "", "mode": "", "label": "", "emoji": "", "color": "", "meaning": ""}


def photo_selected_tag_key(photo):
    return str(photo_selected_tag_meta(photo).get("key") or "")


def photo_selected_tag_mode(photo):
    return str(photo_selected_tag_meta(photo).get("mode") or "")


def photo_selected_tag_values(photo):
    meta = photo_selected_tag_meta(photo)
    key = str(meta.get("key") or "")
    if meta.get("mode") == "parenting":
        return "", key
    return key, ""


def selection_item_tag_values(item):
    """Resolve one tag from an AI-selected still, including legacy dual-tag rows."""
    item = item if isinstance(item, dict) else {}
    emotion_record = item.get("emotion")
    parenting_record = item.get("parenting_tag")
    emotion_key = normalize_photo_emotion_key(emotion_record)
    parenting_key = normalize_parenting_tag_key(parenting_record)
    if emotion_key and parenting_key:
        emotion_at = str(emotion_record.get("updated_at") or "") if isinstance(emotion_record, dict) else ""
        parenting_at = str(parenting_record.get("updated_at") or "") if isinstance(parenting_record, dict) else ""
        if parenting_at and (not emotion_at or parenting_at > emotion_at):
            emotion_key = ""
        else:
            parenting_key = ""
    return emotion_key, parenting_key


def photo_tag_meta_from_key(key):
    key = str(key or "")
    if key in PHOTO_EMOTIONS:
        meta = dict(PHOTO_EMOTIONS[key])
        meta.update({"key": key, "mode": "normal"})
        return meta
    if key in PARENTING_TAGS:
        meta = dict(PARENTING_TAGS[key])
        meta.update({"key": key, "mode": "parenting"})
        return meta
    return {"key": "", "mode": "", "label": "", "emoji": "", "color": "", "meaning": ""}


def photo_emotion_record(emotion_key, source="child_tap_cycle_v168"):
    """Return the persisted reflection_json payload for one of the six v159 feelings."""
    emotion_key = normalize_photo_emotion_key(emotion_key)
    if not emotion_key:
        return None
    meta = PHOTO_EMOTIONS[emotion_key]
    return {
        "key": emotion_key,
        "label": meta["label"],
        "emoji": meta["emoji"],
        "color": meta["color"],
        "updated_at": now_jst().isoformat(),
        "source": str(source or "child_tap_cycle_v168"),
    }


def next_photo_emotion_key(current):
    current = normalize_photo_emotion_key(current)
    cycle = ("",) + PHOTO_EMOTION_ORDER
    try:
        index = cycle.index(current)
    except ValueError:
        index = 0
    return cycle[(index + 1) % len(cycle)]


def photo_emotion_counts(photos):
    """Count the one selected tag per photo across both mode palettes."""
    counts = {key: 0 for key in ALL_PHOTO_TAG_ORDER}
    selected = 0
    for photo in diary_photos_only(photos or []):
        key = photo_selected_tag_key(photo)
        if key in counts:
            counts[key] += 1
            selected += 1
    return counts, selected


def photo_emotion_summary_text(photos, include_unset=True):
    photos = diary_photos_only(photos or [])
    counts, selected = photo_emotion_counts(photos)
    parts = []
    for key in ALL_PHOTO_TAG_ORDER:
        count = int(counts.get(key) or 0)
        if not count:
            continue
        meta = photo_tag_meta_from_key(key)
        parts.append(f"{meta['emoji']}{meta['label']} {count}枚")
    unset = max(0, len(photos) - selected)
    if include_unset and unset:
        parts.append(f"未設定 {unset}枚")
    return " ／ ".join(parts)


def _invalidate_monthly_review_for_trip(trip_id):
    """Emotion changes invalidate any saved monthly interpretation for that day."""
    try:
        trip = get_trip(trip_id) or {}
        trip_date = str(trip.get("trip_date") or "")
        month_key = trip_date[:7] if len(trip_date) >= 7 else ""
        if not month_key:
            return
        first_day, _ = month_bounds(month_key)
        supabase_client().table(MONTHLY_TABLE).delete().eq(
            "review_month", first_day
        ).eq("family_key", current_family_key()).eq("member_key", current_member_key()).execute()
        for key in (
            f"monthly_review_{month_key}",
            f"monthly_audio_{month_key}",
            f"monthly_audio_pending_{month_key}",
        ):
            st.session_state.pop(key, None)
    except Exception:
        # Emotion tagging itself must still succeed even if a stale monthly cache
        # cannot be invalidated at this moment.
        pass


def _refresh_after_photo_emotion_changes(trip_ids):
    """Refresh caches/derived diary data once after one or more emotion writes.

    v159 persists browser-local choices only on the next real app interaction.
    Expensive diary/monthly refresh work is then batched once for all pending changes.
    """
    resolved = []
    seen = set()
    for value in trip_ids or []:
        key = str(value or "").strip()
        if key and key not in seen:
            seen.add(key)
            resolved.append(key)
    _invalidate_fast_db_cache()
    for resolved_trip_id in resolved:
        _invalidate_monthly_review_for_trip(resolved_trip_id)
        try:
            existing = get_diary_for_trip(resolved_trip_id)
            if existing:
                trip = get_trip(resolved_trip_id) or {}
                photos = diary_photos_only(list_trip_photos(resolved_trip_id))
                create_and_save_diary_from_photos(
                    trip,
                    photos,
                    requested_title=str(existing.get("title") or "").strip() or None,
                    reason="emotion_change_v159_deferred",
                )
        except Exception:
            pass


def update_photo_emotion(photo_id, emotion_key, trip_id=None, refresh_related=True):
    """Persist one six-choice feeling tag.

    The optional refresh_related=False path is used by v158 batched UI commits so
    multiple rapid taps do not repeat diary/monthly refresh work for every tap.
    """
    emotion_key = normalize_photo_emotion_key(emotion_key)
    if emotion_key and emotion_key not in PHOTO_EMOTIONS:
        raise ValueError("感情の種類を確認できませんでした。")

    client = supabase_client()
    query = (
        client
        .table(PHOTO_TABLE)
        .select("id,trip_id,reflection_json")
        .eq("id", photo_id)
        .eq("family_key", current_family_key()).eq("member_key", current_member_key())
        .limit(1)
        .execute()
    )
    row = (query.data or [None])[0] or {}
    if not row.get("id"):
        raise ValueError("感情を設定する写真が見つかりませんでした。")
    resolved_trip_id = str(trip_id or row.get("trip_id") or "")
    reflection = row.get("reflection_json") or {}
    if not isinstance(reflection, dict):
        reflection = {}

    if emotion_key:
        reflection["emotion"] = photo_emotion_record(emotion_key, source="child_tap_cycle_v168")
        reflection.pop("parenting_tag", None)
    else:
        reflection.pop("emotion", None)

    (
        client
        .table(PHOTO_TABLE)
        .update({"reflection_json": reflection})
        .eq("id", photo_id)
        .eq("family_key", current_family_key()).eq("member_key", current_member_key())
        .execute()
    )
    if refresh_related:
        _refresh_after_photo_emotion_changes([resolved_trip_id] if resolved_trip_id else [])
    return emotion_key


def update_photo_emotions_batch(changes, valid_photo_ids=None, trip_id=None):
    """Persist only the final emotion for each photo after a burst of taps."""
    valid = {str(value) for value in (valid_photo_ids or []) if str(value)} if valid_photo_ids is not None else None
    latest = {}
    for change in changes or []:
        if not isinstance(change, dict):
            continue
        photo_id = str(change.get("photo_id") or "").strip()
        if not photo_id or (valid is not None and photo_id not in valid):
            continue
        latest[photo_id] = normalize_photo_emotion_key(change.get("emotion"))
    if not latest:
        return {}

    touched_trips = set()
    for photo_id, emotion_key in latest.items():
        # The supplied trip_id is authoritative for the normal diary/recent-photo
        # views. update_photo_emotion still resolves the row trip when it is absent.
        update_photo_emotion(photo_id, emotion_key, trip_id=trip_id, refresh_related=False)
        if trip_id:
            touched_trips.add(str(trip_id))
    if not touched_trips:
        try:
            rows = (
                supabase_client().table(PHOTO_TABLE)
                .select("id,trip_id")
                .in_("id", list(latest.keys()))
                .eq("family_key", current_family_key())
                .eq("member_key", current_member_key())
                .execute()
            ).data or []
            touched_trips.update(str(row.get("trip_id") or "") for row in rows if row.get("trip_id"))
        except Exception:
            pass
    _refresh_after_photo_emotion_changes(touched_trips)
    return latest


def update_photo_parenting_tag(photo_id, tag_key, trip_id=None, refresh_related=True):
    """Persist one parent-facing child-rearing tag independently of normal emotion."""
    tag_key = normalize_parenting_tag_key(tag_key)
    if tag_key and tag_key not in PARENTING_TAGS:
        raise ValueError("こどもーどアイコンの種類を確認できませんでした。")

    client = supabase_client()
    query = (
        client.table(PHOTO_TABLE)
        .select("id,trip_id,reflection_json")
        .eq("id", photo_id)
        .eq("family_key", current_family_key()).eq("member_key", current_member_key())
        .limit(1)
        .execute()
    )
    row = (query.data or [None])[0] or {}
    if not row.get("id"):
        raise ValueError("こどもーどアイコンを設定する写真が見つかりませんでした。")
    resolved_trip_id = str(trip_id or row.get("trip_id") or "")
    reflection = row.get("reflection_json") or {}
    if not isinstance(reflection, dict):
        reflection = {}

    if tag_key:
        reflection["parenting_tag"] = parenting_tag_record(tag_key, source="parent_tap_cycle_v168")
        reflection.pop("emotion", None)
    else:
        reflection.pop("parenting_tag", None)

    (
        client.table(PHOTO_TABLE)
        .update({"reflection_json": reflection})
        .eq("id", photo_id)
        .eq("family_key", current_family_key()).eq("member_key", current_member_key())
        .execute()
    )
    if refresh_related:
        _refresh_after_photo_emotion_changes([resolved_trip_id] if resolved_trip_id else [])
    return tag_key


def update_photo_parenting_tags_batch(changes, valid_photo_ids=None, trip_id=None):
    """Persist final parenting-mode tags when the next real app interaction occurs."""
    valid = {str(value) for value in (valid_photo_ids or []) if str(value)} if valid_photo_ids is not None else None
    latest = {}
    for change in changes or []:
        if not isinstance(change, dict):
            continue
        photo_id = str(change.get("photo_id") or "").strip()
        if not photo_id or (valid is not None and photo_id not in valid):
            continue
        latest[photo_id] = normalize_parenting_tag_key(change.get("parenting"))
    if not latest:
        return {}

    touched_trips = set()
    for photo_id, tag_key in latest.items():
        update_photo_parenting_tag(photo_id, tag_key, trip_id=trip_id, refresh_related=False)
        if trip_id:
            touched_trips.add(str(trip_id))
    if not touched_trips:
        try:
            rows = (
                supabase_client().table(PHOTO_TABLE)
                .select("id,trip_id")
                .in_("id", list(latest.keys()))
                .eq("family_key", current_family_key())
                .eq("member_key", current_member_key())
                .execute()
            ).data or []
            touched_trips.update(str(row.get("trip_id") or "") for row in rows if row.get("trip_id"))
        except Exception:
            pass
    _refresh_after_photo_emotion_changes(touched_trips)
    return latest



def update_photo_tags_combined_v166(emotion_changes=None, parenting_changes=None):
    """Persist both tag axes with one row read/write per photo and one diary refresh."""
    emotion_latest = {}
    for change in emotion_changes or []:
        if isinstance(change, dict):
            pid = str(change.get("photo_id") or "").strip()
            if pid:
                emotion_latest[pid] = normalize_photo_emotion_key(change.get("emotion"))
    parenting_latest = {}
    for change in parenting_changes or []:
        if isinstance(change, dict):
            pid = str(change.get("photo_id") or "").strip()
            if pid:
                parenting_latest[pid] = normalize_parenting_tag_key(change.get("parenting"))

    photo_ids = sorted(set(emotion_latest) | set(parenting_latest))
    if not photo_ids:
        return {"emotion": emotion_latest, "parenting": parenting_latest}

    client = supabase_client()
    rows = (
        client.table(PHOTO_TABLE)
        .select("id,trip_id,reflection_json")
        .in_("id", photo_ids)
        .eq("family_key", current_family_key())
        .eq("member_key", current_member_key())
        .execute()
    ).data or []
    row_map = {str(row.get("id") or ""): row for row in rows if row.get("id")}
    touched_trips = set()

    for photo_id in photo_ids:
        row = row_map.get(photo_id)
        if not row:
            continue
        reflection = row.get("reflection_json") or {}
        if not isinstance(reflection, dict):
            reflection = {}
        else:
            reflection = dict(reflection)

        emotion_present = photo_id in emotion_latest
        parenting_present = photo_id in parenting_latest
        emotion_key = emotion_latest.get(photo_id, "") if emotion_present else ""
        tag_key = parenting_latest.get(photo_id, "") if parenting_present else ""

        # A non-empty choice in either palette replaces the other palette's value.
        if emotion_present and emotion_key:
            reflection["emotion"] = photo_emotion_record(emotion_key, source="child_tap_batch_v168")
            reflection.pop("parenting_tag", None)
        elif parenting_present and tag_key:
            reflection["parenting_tag"] = parenting_tag_record(tag_key, source="parent_tap_batch_v168")
            reflection.pop("emotion", None)
        else:
            if emotion_present:
                reflection.pop("emotion", None)
            if parenting_present:
                reflection.pop("parenting_tag", None)

        (
            client.table(PHOTO_TABLE)
            .update({"reflection_json": reflection})
            .eq("id", photo_id)
            .eq("family_key", current_family_key())
            .eq("member_key", current_member_key())
            .execute()
        )
        trip_id = str(row.get("trip_id") or "").strip()
        if trip_id:
            touched_trips.add(trip_id)

    _refresh_after_photo_emotion_changes(touched_trips)
    return {"emotion": emotion_latest, "parenting": parenting_latest}


# ============================================================
# Deferred browser emotion persistence (v159)
# ============================================================
# Choosing a feeling must not cause a Streamlit rerun. Browser components write a
# compact pending payload into the current URL with history.replaceState(), which
# does not navigate. The next real app interaction/rerun consumes it here *before*
# the requested page action is rendered, so diary generation / keeping a moment can
# use the newest choices without making emotion taps themselves reload the page.
PENDING_EMOTION_QUERY_PARAM = "feel_v159"


def _decode_pending_emotion_query(raw_value):
    raw = str(raw_value or "").strip()
    if not raw or len(raw) > 24000:
        return None
    try:
        padded = raw + ("=" * ((4 - len(raw) % 4) % 4))
        payload = json.loads(base64.urlsafe_b64decode(padded.encode("ascii")).decode("utf-8"))
    except Exception:
        return None
    return payload if isinstance(payload, dict) else None


def _query_param_scalar(name):
    try:
        value = st.query_params.get(name, "")
    except Exception:
        return ""
    if isinstance(value, (list, tuple)):
        value = value[-1] if value else ""
    return str(value or "").strip()


def consume_pending_emotion_query():
    """Persist browser-only feeling choices on the next non-emotion app rerun.

    Returns True when a pending payload was successfully consumed. Failures leave
    the URL payload intact so a later interaction can retry instead of losing the
    child's selections.
    """
    raw = _query_param_scalar(PENDING_EMOTION_QUERY_PARAM)
    payload = _decode_pending_emotion_query(raw)
    if not payload:
        return False

    token = str(payload.get("t") or "").strip()
    if not token:
        return False

    # Never apply one person's browser-pending choices to another login.
    if str(payload.get("f") or "") != str(current_family_key()) or str(payload.get("m") or "") != str(current_member_key()):
        st.session_state["_emotion_query_ack_token"] = token
        return False

    if token == str(st.session_state.get("_emotion_query_processed_token") or ""):
        st.session_state["_emotion_query_ack_token"] = token
        return True

    try:
        photo_map = payload.get("p") or {}
        photo_changes = []
        if isinstance(photo_map, dict):
            for photo_id, emotion in photo_map.items():
                pid = str(photo_id or "").strip()
                if pid:
                    photo_changes.append({"photo_id": pid, "emotion": normalize_photo_emotion_key(emotion)})
        parenting_map = payload.get("g") or {}
        parenting_changes = []
        if isinstance(parenting_map, dict):
            for photo_id, parenting in parenting_map.items():
                pid = str(photo_id or "").strip()
                if pid:
                    parenting_changes.append({"photo_id": pid, "parenting": normalize_parenting_tag_key(parenting)})
        if photo_changes or parenting_changes:
            update_photo_tags_combined_v166(photo_changes, parenting_changes)

        moments = payload.get("x") or {}
        if isinstance(moments, dict):
            for video_id, state in moments.items():
                vid = str(video_id or "").strip()
                if not vid or not isinstance(state, dict):
                    continue
                try:
                    round_number = max(0, int(state.get("r") or 0))
                except Exception:
                    round_number = 0

                selected_raw = state.get("s") or []
                selected = sorted({
                    int(value)
                    for value in selected_raw
                    if str(value).strip().lstrip("-").isdigit() and int(value) > 0
                }) if isinstance(selected_raw, (list, tuple)) else []
                st.session_state[f"_moments_tap_selected_{vid}_{round_number}"] = selected

                emotion_map = state.get("e") or {}
                changes = []
                if isinstance(emotion_map, dict):
                    for rank_value, emotion in emotion_map.items():
                        try:
                            rank = int(rank_value)
                        except Exception:
                            rank = 0
                        if rank > 0:
                            changes.append({"rank": rank, "emotion": normalize_photo_emotion_key(emotion)})

                parenting_state_map = state.get("g") or {}
                parenting_changes = []
                if isinstance(parenting_state_map, dict):
                    for rank_value, parenting in parenting_state_map.items():
                        try:
                            rank = int(rank_value)
                        except Exception:
                            rank = 0
                        if rank > 0:
                            parenting_changes.append({"rank": rank, "parenting": normalize_parenting_tag_key(parenting)})
                if not changes and not parenting_changes:
                    continue

                row = (
                    supabase_client().table(PHOTO_TABLE)
                    .select("*")
                    .eq("id", vid)
                    .eq("family_key", current_family_key())
                    .eq("member_key", current_member_key())
                    .limit(1)
                    .execute()
                ).data or []
                video_photo = row[0] if row else None
                if video_photo and photo_is_video(video_photo):
                    update_video_ai_selection_tags(
                        video_photo,
                        emotion_changes=changes,
                        parenting_changes=parenting_changes,
                    )

        st.session_state["_emotion_query_processed_token"] = token
        st.session_state["_emotion_query_ack_token"] = token
        return True
    except Exception as exc:
        st.session_state["_emotion_sync_warning"] = (
            "選んだ気持ちの保存を次の操作でもう一度試します。"
        )
        st.session_state["_emotion_sync_warning_detail"] = _safe_error_text(exc, 700)
        return False


