# ============================================================
# Browser-only pending tag flush bridge (v166)
# ============================================================
# Photo taps never contact Streamlit. They only update one localStorage envelope.
# The next real app rerun (navigation, display-mode change, save action, etc.) mounts
# this bridge; it sends the whole pending envelope once, and Python persists it in a
# batch. This keeps tapping and mode switching immediate while avoiding timer-driven
# reruns that could destabilize enlarged/list views.
PENDING_TAG_STORE_V166 = "tokyo_burari_pending_tags_v166"

_PENDING_TAG_SYNC_JS = r"""
const STORE_KEY = 'tokyo_burari_pending_tags_v166';
const REGISTRY_KEY = Symbol.for('tokyo_burari_pending_tag_sync_v166');
const registry = globalThis[REGISTRY_KEY] || new Map();
globalThis[REGISTRY_KEY] = registry;

export default function(component) {
  const { data, setTriggerValue } = component;
  const familyKey = String(data?.family_key || '');
  const memberKey = String(data?.member_key || '');
  const ackToken = String(data?.ack_token || '');
  const instanceKey = `${familyKey}|${memberKey}`;
  const runtime = registry.get(instanceKey) || { lastSent: '' };
  registry.set(instanceKey, runtime);
  if (!familyKey || !memberKey) return;

  const parse = (raw) => {
    try {
      const payload = JSON.parse(String(raw || 'null'));
      return payload && typeof payload === 'object' ? payload : null;
    } catch (_) { return null; }
  };

  try {
    let raw = String(localStorage.getItem(STORE_KEY) || '');
    let payload = parse(raw);

    if (ackToken && payload && String(payload.t || '') === ackToken) {
      localStorage.removeItem(STORE_KEY);
      runtime.lastSent = '';
      raw = '';
      payload = null;
    }

    if (!payload || Number(payload.v) !== 166) return;
    if (String(payload.f || '') !== familyKey || String(payload.m || '') !== memberKey) return;
    const token = String(payload.t || '');
    if (!token || token === runtime.lastSent) return;

    runtime.lastSent = token;
    queueMicrotask(() => setTriggerValue('pending_payload', payload));
  } catch (_) {}
}
"""

try:
    pending_tag_sync_component_v166 = st.components.v2.component(
        "tokyo_burari_pending_tag_sync_v166",
        js=_PENDING_TAG_SYNC_JS,
    )
except Exception:
    pending_tag_sync_component_v166 = None


def _apply_pending_tag_payload_v166(payload):
    if not isinstance(payload, dict) or int(payload.get("v") or 0) != 166:
        return False
    token = str(payload.get("t") or "").strip()
    if not token:
        return False
    if str(payload.get("f") or "") != str(current_family_key()) or str(payload.get("m") or "") != str(current_member_key()):
        return False
    if token == str(st.session_state.get("_pending_tag_v166_processed_token") or ""):
        st.session_state["_pending_tag_v166_ack_token"] = token
        return True

    try:
        photo_changes = []
        for photo_id, emotion in (payload.get("p") or {}).items() if isinstance(payload.get("p"), dict) else []:
            pid = str(photo_id or "").strip()
            if pid:
                photo_changes.append({"photo_id": pid, "emotion": normalize_photo_emotion_key(emotion)})
        parenting_changes = []
        for photo_id, parenting in (payload.get("g") or {}).items() if isinstance(payload.get("g"), dict) else []:
            pid = str(photo_id or "").strip()
            if pid:
                parenting_changes.append({"photo_id": pid, "parenting": normalize_parenting_tag_key(parenting)})
        if photo_changes or parenting_changes:
            update_photo_tags_combined_v166(photo_changes, parenting_changes)

        moments = payload.get("x") or {}
        if isinstance(moments, dict):
            for video_id, state in moments.items():
                vid = str(video_id or "").strip()
                if not vid or not isinstance(state, dict):
                    continue
                try:
                    round_number = max(0, int(state.get("r") or 0))
                except Exception:
                    round_number = 0

                selected_raw = state.get("s") or []
                selected = sorted({
                    int(value)
                    for value in selected_raw
                    if str(value).strip().lstrip("-").isdigit() and int(value) > 0
                }) if isinstance(selected_raw, (list, tuple)) else []
                st.session_state[f"_moments_tap_selected_{vid}_{round_number}"] = selected

                emotion_changes = []
                emotion_map = state.get("e") or {}
                if isinstance(emotion_map, dict):
                    for rank_value, emotion in emotion_map.items():
                        try:
                            rank = int(rank_value)
                        except Exception:
                            rank = 0
                        if rank > 0:
                            emotion_changes.append({"rank": rank, "emotion": normalize_photo_emotion_key(emotion)})

                parenting_rank_changes = []
                parenting_map = state.get("g") or {}
                if isinstance(parenting_map, dict):
                    for rank_value, parenting in parenting_map.items():
                        try:
                            rank = int(rank_value)
                        except Exception:
                            rank = 0
                        if rank > 0:
                            parenting_rank_changes.append({"rank": rank, "parenting": normalize_parenting_tag_key(parenting)})

                if not emotion_changes and not parenting_rank_changes:
                    continue
                row = (
                    supabase_client().table(PHOTO_TABLE)
                    .select("*")
                    .eq("id", vid)
                    .eq("family_key", current_family_key())
                    .eq("member_key", current_member_key())
                    .limit(1)
                    .execute()
                ).data or []
                video_photo = row[0] if row else None
                if video_photo and photo_is_video(video_photo):
                    update_video_ai_selection_tags(
                        video_photo,
                        emotion_changes=emotion_changes,
                        parenting_changes=parenting_rank_changes,
                    )

        st.session_state["_pending_tag_v166_processed_token"] = token
        st.session_state["_pending_tag_v166_ack_token"] = token
        return True
    except Exception as exc:
        st.session_state["_emotion_sync_warning"] = "選んだアイコンの保存を次の操作でもう一度試します。"
        st.session_state["_emotion_sync_warning_detail"] = _safe_error_text(exc, 700)
        return False


def sync_pending_tags_from_browser_v166():
    """Flush browser-local photo/video tags only when some real app rerun occurs."""
    if pending_tag_sync_component_v166 is None:
        return False
    result = pending_tag_sync_component_v166(
        data={
            "family_key": current_family_key(),
            "member_key": current_member_key(),
            "ack_token": str(st.session_state.get("_pending_tag_v166_ack_token") or ""),
            "scan_nonce": time.time_ns(),
        },
        key="pending_tag_sync_instance_v166",
        on_pending_payload_change=lambda: None,
    )
    payload = getattr(result, "pending_payload", None)
    if isinstance(payload, dict):
        return _apply_pending_tag_payload_v166(payload)
    return False


# ============================================================
# Browser history bridge
# ============================================================
# Streamlit session-state navigation does not create browser history entries by
# itself. This small component mirrors each app screen into window.history so
# Chrome/Safari back and forward buttons move between app screens first.
_HISTORY_JS = r"""
export default function(component) {
  const { data, setTriggerValue } = component;
  const validPages = new Set(['home', 'camera', 'videos', 'moments', 'diary', 'review', 'review_monthly', 'review_tag', 'review_history', 'nearby', 'toilets', 'settings']);
  const marker = '__tokyo_burari_page__';
  const guardMarker = '__tokyo_burari_first_level_guard__';
  const requestedPage = validPages.has(data?.page) ? data.page : 'home';
  const action = data?.action || 'sync';
  const navigationNode = String(data?.node || requestedPage);
  const interceptHierarchyBack = Boolean(data?.intercept_hierarchy_back) && requestedPage !== 'home';
  const firstLevelBackToHome = requestedPage !== 'home' && navigationNode === requestedPage && !interceptHierarchyBack;
  const pendingFeelingParam = 'feel_v159';
  const pendingFeelingStore = 'tokyo_burari_pending_feelings_v159';
  const restorePendingFeelingParam = () => {
    try {
      const url = new URL(window.location.href);
      if (url.searchParams.get(pendingFeelingParam)) return false;
      const raw = String(localStorage.getItem(pendingFeelingStore) || '');
      if (!raw) return false;
      url.searchParams.set(pendingFeelingParam, raw);
      window.history.replaceState(window.history.state || {}, '', url.pathname + url.search + url.hash);
      return true;
    } catch (_) { return false; }
  };

  const restoredPendingFeeling = restorePendingFeelingParam();
  if (restoredPendingFeeling) {
    queueMicrotask(() => setTriggerValue('pending_restore', `${Date.now()}:${Math.random()}`));
  }

  const pageFromUrl = () => {
    try {
      const value = new URL(window.location.href).searchParams.get('view');
      return validPages.has(value) ? value : 'home';
    } catch (_) {
      return 'home';
    }
  };

  const pageFromHistory = () => {
    const value = window.history.state && window.history.state[marker];
    return validPages.has(value) ? value : pageFromUrl();
  };

  const urlFor = (page) => {
    const url = new URL(window.location.href);
    if (page === 'home') {
      url.searchParams.delete('view');
    } else {
      url.searchParams.set('view', page);
    }
    return url.pathname + url.search + url.hash;
  };

  let currentPage = pageFromHistory();
  const state = window.history.state || {};

  // Mark the entry used to open the app as the app's home/current entry.
  if (!validPages.has(state[marker])) {
    const initialPage = pageFromUrl();
    window.history.replaceState(
      { ...state, [marker]: initialPage },
      '',
      urlFor(initialPage)
    );
    currentPage = initialPage;
  }

  if (action === 'push' && currentPage !== requestedPage) {
    window.history.pushState(
      { ...(window.history.state || {}), [marker]: requestedPage },
      '',
      urlFor(requestedPage)
    );
    currentPage = requestedPage;
  } else if (action === 'replace' && currentPage !== requestedPage) {
    window.history.replaceState(
      { ...(window.history.state || {}), [marker]: requestedPage },
      '',
      urlFor(requestedPage)
    );
    currentPage = requestedPage;
  } else if (action === 'sync' && currentPage !== requestedPage) {
    // This covers a page reload or a browser-restored tab whose URL/history
    // already points at an internal app screen.
    queueMicrotask(() => setTriggerValue('page', currentPage));
  }

  // Android/PWA can return from an external Maps app with no usable browser entry
  // behind the current first-level screen. Add one same-page guard entry so the next
  // native Back always fires popstate instead of closing the web app. It is armed once
  // per first-level page and survives the trip out to Google Maps.
  if (firstLevelBackToHome && currentPage === requestedPage) {
    const currentState = window.history.state || {};
    if (currentState[guardMarker] !== requestedPage) {
      window.history.pushState(
        { ...currentState, [marker]: requestedPage, [guardMarker]: requestedPage },
        '',
        urlFor(requestedPage)
      );
    }
  } else if (requestedPage === 'home') {
    const currentState = window.history.state || {};
    if (currentState[guardMarker]) {
      const cleanState = { ...currentState };
      delete cleanState[guardMarker];
      cleanState[marker] = 'home';
      window.history.replaceState(cleanState, '', urlFor('home'));
    }
  }

  const onPopState = (event) => {
    // A native browser Back can move to an older URL before Streamlit reruns.
    // Restore browser-local pending feelings onto that history entry first.
    restorePendingFeelingParam();
    if (interceptHierarchyBack) {
      // The phone/browser Back control must mean "one folder level up", not
      // "whatever screen happened to be visited previously". Restore the app
      // entry immediately, then let Python apply the fixed parent mapping.
      window.history.pushState(
        { ...(window.history.state || {}), [marker]: requestedPage },
        '',
        urlFor(requestedPage)
      );
      const token = `${navigationNode}:${Date.now()}:${Math.random()}`;
      setTriggerValue('hierarchy_back', token);
      return;
    }
    if (firstLevelBackToHome) {
      // We have just popped the synthetic guard. Convert the revealed entry to Home
      // before Streamlit rerenders, so Android Back never falls through and closes the app.
      const homeState = { ...(event.state || {}) };
      delete homeState[guardMarker];
      homeState[marker] = 'home';
      window.history.replaceState(homeState, '', urlFor('home'));
      setTriggerValue('page', 'home');
      return;
    }
    const statePage = event.state && event.state[marker];
    const target = validPages.has(statePage) ? statePage : pageFromUrl();
    setTriggerValue('page', validPages.has(target) ? target : 'home');
  };

  window.addEventListener('popstate', onPopState);
  return () => window.removeEventListener('popstate', onPopState);
}
"""

try:
    browser_history_component = st.components.v2.component(
        'tokyo_burari_browser_history_v208',
        js=_HISTORY_JS,
    )
except Exception:
    browser_history_component = None


