_VIDEO_LIBRARY_GRID_JS = r"""
export default function(component) {
  const { parentElement, data, setTriggerValue } = component;
  const grid = parentElement.querySelector('#video-library-grid');
  if (!grid) return;

  grid.replaceChildren();
  const videos = Array.isArray(data?.videos) ? data.videos.slice(0, 9) : [];

  for (let index = 0; index < 9; index += 1) {
    const video = videos[index];
    if (!video) {
      const empty = document.createElement('div');
      empty.className = 'video-library-empty';
      grid.appendChild(empty);
      continue;
    }

    const id = String(video.id || '');
    const card = document.createElement('div');
    card.className = 'video-library-card';

    const openButton = document.createElement('button');
    openButton.type = 'button';
    openButton.className = 'video-library-open';
    openButton.setAttribute('aria-label', `${String(video.title || '動画')}を見る`);

    const imageWrap = document.createElement('div');
    imageWrap.className = 'video-library-image-wrap';
    if (video.src) {
      const img = document.createElement('img');
      img.src = String(video.src);
      img.alt = '動画サムネイル';
      img.loading = 'lazy';
      img.decoding = 'async';
      img.fetchPriority = 'low';
      imageWrap.appendChild(img);
    } else {
      const placeholder = document.createElement('div');
      placeholder.className = 'video-library-placeholder';
      placeholder.textContent = '動画';
      imageWrap.appendChild(placeholder);
    }

    const play = document.createElement('div');
    play.className = 'video-library-play';
    play.textContent = '▶';
    imageWrap.appendChild(play);

    const info = document.createElement('div');
    info.className = 'video-library-info';

    const title = document.createElement('div');
    title.className = 'video-library-title';
    title.textContent = String(video.title || '');
    info.appendChild(title);

    const meta = document.createElement('div');
    meta.className = 'video-library-meta';
    meta.textContent = String(video.meta || '');
    info.appendChild(meta);

    const status = document.createElement('div');
    status.className = 'video-library-status';
    status.textContent = String(video.status || '');
    info.appendChild(status);

    openButton.appendChild(imageWrap);
    openButton.appendChild(info);
    openButton.addEventListener('click', () => {
      if (id) setTriggerValue('open_video_id', id);
    });

    const deleteButton = document.createElement('button');
    deleteButton.type = 'button';
    deleteButton.className = 'video-library-delete';
    deleteButton.textContent = '×';
    deleteButton.setAttribute('aria-label', `${String(video.title || '動画')}を削除`);
    deleteButton.addEventListener('click', (event) => {
      event.preventDefault();
      event.stopPropagation();
      if (id) setTriggerValue('delete_video_id', id);
    });

    card.appendChild(openButton);
    card.appendChild(deleteButton);
    grid.appendChild(card);
  }
}
"""

video_library_grid_component = None
_video_library_grid_component_initialized = False


def _get_video_library_grid_component():
    global video_library_grid_component, _video_library_grid_component_initialized
    if _video_library_grid_component_initialized:
        return video_library_grid_component
    _video_library_grid_component_initialized = True
    try:
        video_library_grid_component = st.components.v2.component(
            "tokyo_burari_video_library_grid_v128",
            html=_VIDEO_LIBRARY_GRID_HTML,
            css=_VIDEO_LIBRARY_GRID_CSS,
            js=_VIDEO_LIBRARY_GRID_JS,
        )
    except Exception:
        video_library_grid_component = None
    return video_library_grid_component


def page_videos():
    delete_notice = st.session_state.pop("_video_delete_notice", None)
    if delete_notice:
        st.success(delete_notice)

    page_top(
        "🎞️ 動画保管庫",
        "保存された元動画を3×3で確認できます。動画を押すと再生、右上の×で削除できます。",
    )

    try:
        videos = list_member_videos_for_moments(limit=500)
    except Exception as exc:
        st.error("動画保管庫を読み込めませんでした。")
        with st.expander("保護者向け詳細"):
            st.code(str(exc))
        return

    quota = video_storage_quota_bytes()
    try:
        usage = current_video_storage_usage_bytes()
    except Exception:
        usage = sum(
            max(0, int(photo_media_metadata(v).get("video_size_bytes") or 0))
            for v in videos
        )
    if quota > 0:
        st.caption(
            f"DB登録済み動画：{len(videos)}本 ／ 動画Storage実使用量 {format_storage_size(usage)} / "
            f"上限 {format_storage_size(quota)} ／ 残り {format_storage_size(max(0, quota - usage))}"
        )
    else:
        st.caption(f"DB登録済み動画：{len(videos)}本 ／ 動画Storage実使用量 {format_storage_size(usage)} ／ 総容量上限は未設定")

    repair_notice = st.session_state.pop("_video_storage_repair_notice", None)
    if repair_notice:
        st.success(repair_notice)
    _render_video_storage_repair_panel(len(videos))

    if not videos:
        st.info("DBに登録された動画はありません。上の「Storage実体を確認」で、未登録の動画が残っていないか確認できます。")
        return

    # Nine videos per page keeps the vault as an exact 3×3 grid on both desktop
    # and mobile. The custom component never collapses the three columns.
    per_page = 9
    page_count = max(1, (len(videos) + per_page - 1) // per_page)
    page_key = "_video_library_grid_page"
    try:
        current_page = int(st.session_state.get(page_key) or 0)
    except Exception:
        current_page = 0
    current_page = max(0, min(current_page, page_count - 1))
    st.session_state[page_key] = current_page

    start_index = current_page * per_page
    visible_videos = videos[start_index:start_index + per_page]
    cards = []
    for local_index, video_row in enumerate(visible_videos):
        metadata = photo_media_metadata(video_row)
        size_value = max(0, int(metadata.get("video_size_bytes") or 0))
        duration_ms = max(0, int(metadata.get("video_duration_ms") or 0))
        detail_parts = []
        if duration_ms:
            detail_parts.append(f"{max(1, round(duration_ms / 1000))}秒")
        if size_value:
            detail_parts.append(format_storage_size(size_value))

        selection = metadata.get("ai_selection") or {}
        status_label = ""
        if isinstance(selection, dict):
            status = str(selection.get("status") or "").lower()
            if status == "processing":
                stage = str(selection.get("stage") or "").strip().lower()
                status_label = "✨ 最大20候補を準備中" if stage == "candidate_preparation" else "✨ いい瞬間を自動選定中"
            elif status in {"", "waiting_candidates"}:
                status_label = "✨ 自動処理を開始待ち"
            elif status == "ready":
                status_label = "✨ いい瞬間を確認できます"
            elif status == "reviewed":
                status_label = "✓ いい瞬間を確認済み"
            elif status == "error":
                status_label = "AI選定は未完了"

        poster_path = str(video_row.get("storage_path") or "").strip()
        preview_url = photo_display_url(video_row)
        if not preview_url and poster_path:
            try:
                preview_url = thumbnail_photo_data_url(poster_path, max_px=520, quality=82)
            except Exception:
                preview_url = ""

        cards.append(
            {
                "id": str(video_row.get("id") or ""),
                "src": preview_url,
                "title": _moments_video_title(video_row),
                "meta": " ／ ".join(detail_parts),
                "status": status_label,
            }
        )

    grid_component = _get_video_library_grid_component()
    handled_action = False
    if grid_component is not None:
        serial_key = "_video_library_grid_serial"
        serial = int(st.session_state.get(serial_key) or 0)
        result = grid_component(
            data={"videos": cards},
            key=f"video_library_grid_{current_page}_{serial}_{_current_ui_refresh_epoch()}",
            on_open_video_id_change=lambda: None,
            on_delete_video_id_change=lambda: None,
        )
        open_video_id = str(getattr(result, "open_video_id", None) or "").strip()
        delete_video_id = str(getattr(result, "delete_video_id", None) or "").strip()

        if delete_video_id:
            target = next((row for row in visible_videos if str(row.get("id") or "") == delete_video_id), None)
            if target:
                st.session_state[serial_key] = serial + 1
                show_video_delete_dialog(target)
                handled_action = True
        elif open_video_id:
            target = next((row for row in visible_videos if str(row.get("id") or "") == open_video_id), None)
            if target:
                metadata = photo_media_metadata(target)
                detail_parts = []
                duration_ms = max(0, int(metadata.get("video_duration_ms") or 0))
                size_value = max(0, int(metadata.get("video_size_bytes") or 0))
                if duration_ms:
                    detail_parts.append(f"{max(1, round(duration_ms / 1000))}秒")
                if size_value:
                    detail_parts.append(format_storage_size(size_value))
                st.session_state[serial_key] = serial + 1
                show_video_library_dialog(target, _moments_video_title(target), " ／ ".join(detail_parts))
                handled_action = True
    else:
        # Fallback for older Streamlit runtimes. Keep three columns and place an ×
        # control at the upper-right area of each card.
        for row_start in range(0, per_page, 3):
            row_columns = st.columns(3, gap="small")
            for offset in range(3):
                item_index = row_start + offset
                with row_columns[offset]:
                    if item_index >= len(visible_videos):
                        st.write("")
                        continue
                    video_row = visible_videos[item_index]
                    card = cards[item_index]
                    _, delete_col = st.columns([5, 1], gap="small")
                    with delete_col:
                        if st.button(
                            "×",
                            key=f"video_fallback_delete_{current_page}_{item_index}_{video_row.get('id')}",
                            help="この動画を削除",
                        ):
                            show_video_delete_dialog(video_row)
                    if card.get("src"):
                        st.image(card["src"], use_container_width=True)
                    st.caption(card.get("title") or "")
                    if st.button(
                        "見る",
                        use_container_width=True,
                        key=f"video_fallback_open_{current_page}_{item_index}_{video_row.get('id')}",
                    ):
                        show_video_library_dialog(video_row, card.get("title") or "", card.get("meta") or "")

    if page_count > 1 and not handled_action:
        st.caption(f"{current_page + 1} / {page_count}ページ　（1ページ9本）")
        prev_col, next_col = st.columns(2, gap="small")
        with prev_col:
            if st.button(
                "← 前の9本",
                use_container_width=True,
                disabled=current_page <= 0,
                key=f"video_grid_prev_{current_page}",
            ):
                st.session_state[page_key] = max(0, current_page - 1)
                st.rerun()
        with next_col:
            if st.button(
                "次の9本 →",
                use_container_width=True,
                disabled=current_page >= page_count - 1,
                key=f"video_grid_next_{current_page}",
            ):
                st.session_state[page_key] = min(page_count - 1, current_page + 1)
                st.rerun()


def page_moments():
    delete_notice = st.session_state.pop("_video_delete_notice", None)
    if delete_notice:
        st.success(delete_notice)

    page_top(
        "✨ いい瞬間",
        "動画ごとにAIが選んだ瞬間を確認し、気に入った写真だけ日記へ送れます。",
    )

    # v148: keep the display-mode switch in one fixed location directly below
    # the page Back/title area. The mode is page-wide, while each video's selected
    # ranks are shared between list and enlarged views.
    with st.container(key="moments_view_mode_bar"):
        mode_label = st.radio(
            "表示モード",
            ["一覧モード", "拡大モード"],
            horizontal=True,
            key="_moments_view_mode_label",
            label_visibility="collapsed",
        )
    st.markdown(
        """
        <style>
        .st-key-moments_view_mode_bar {
          margin: .05rem 0 .55rem;
          padding: .28rem .42rem;
          border: 1px solid rgba(128,128,128,.20);
          border-radius: 14px;
          background: color-mix(in srgb, var(--background-color, #fff) 94%, rgba(128,128,128,.06) 6%);
        }
        .st-key-moments_view_mode_bar [role="radiogroup"] {
          justify-content: center;
          gap: .35rem;
        }
        .st-key-moments_view_mode_bar label {
          min-height: 42px;
          align-items: center;
        }
        </style>
        """,
        unsafe_allow_html=True,
    )
    view_mode = "enlarge" if mode_label == "拡大モード" else "list"

    notice = st.session_state.pop("_moments_notice", None)
    if notice:
        st.success(notice)
    bulk_delete_detail = st.session_state.pop("_moments_bulk_delete_error_detail", None)
    if bulk_delete_detail:
        with st.expander("削除できなかった動画の詳細"):
            st.code(str(bulk_delete_detail))

    try:
        videos = list_member_videos_for_moments(limit=300)
    except Exception as exc:
        st.error("動画の一覧を読み込めませんでした。")
        with st.expander("保護者向け詳細"):
            st.code(str(exc))
        return

    if not videos:
        st.info("まだ動画がありません。動画を撮影すると、動画保存後にバックグラウンドでAIがいい瞬間を探します。")
        return

    pending = []
    ready = []
    reviewed = []
    for video in videos:
        selection = photo_media_metadata(video).get("ai_selection") or {}
        if not isinstance(selection, dict):
            selection = {}
        status = str(selection.get("status") or "").lower()
        if status == "reviewed":
            reviewed.append(video)
        elif status == "ready" and video_ai_selection_items(video):
            ready.append(video)
        else:
            pending.append(video)

    display_videos = pending + ready
    if display_videos:
        if view_mode == "enlarge":
            # v166: enlarged mode keeps only one source video mounted at a time.
            # This prevents many video players + large still components from building
            # up in the DOM and exhausting mobile browser memory.
            active_key = "_moments_enlarge_unreviewed_index_v166"
            try:
                active_index = int(st.session_state.get(active_key) or 0)
            except Exception:
                active_index = 0
            active_index = max(0, min(active_index, len(display_videos) - 1))
            st.session_state[active_key] = active_index
            _render_moments_picker(display_videos[active_index], active_index, view_mode=view_mode)
            if len(display_videos) > 1:
                next_index = (active_index + 1) % len(display_videos)
                if st.button(
                    f"次の未確認動画へ →（{next_index + 1}/{len(display_videos)}）",
                    use_container_width=True,
                    key=f"moments_next_unreviewed_v166_{active_index}",
                ):
                    st.session_state[active_key] = next_index
                    st.rerun(scope="app")
        else:
            for idx, video in enumerate(display_videos):
                if idx:
                    st.divider()
                _render_moments_picker(video, idx, view_mode=view_mode)
    else:
        st.info("未確認のAIセレクションはありません。")

    if reviewed:
        st.divider()
        st.markdown(f"#### 確認済み動画（{len(reviewed)}本）―再選択できます。")

        bulk_delete_key = "_moments_delete_all_reviewed_confirm"
        if not st.session_state.get(bulk_delete_key):
            if st.button(
                "🗑 確認済み動画を一斉削除",
                use_container_width=True,
                key="moments_delete_all_reviewed_begin",
                help="確認済みの元動画をまとめて削除します。日記に残した静止画は残ります。",
            ):
                st.session_state[bulk_delete_key] = True
                st.rerun(scope="app")
        else:
            st.warning(
                f"確認済み動画{len(reviewed)}本をすべて削除します。"
                "元動画・代表画像・AIの未保存切り取り画像は削除されますが、"
                "すでに日記へ残した静止画は残ります。この操作は元に戻せません。"
            )
            delete_col, cancel_col = st.columns(2, gap="small")
            with delete_col:
                if st.button(
                    "一斉削除する",
                    type="primary",
                    use_container_width=True,
                    key="moments_delete_all_reviewed_yes",
                ):
                    deleted = 0
                    failures = []
                    with st.spinner("確認済み動画を削除しています…"):
                        for reviewed_video in list(reviewed):
                            try:
                                delete_video_and_related_data(reviewed_video)
                                deleted += 1
                            except Exception as exc:
                                failures.append(f"{_moments_video_title(reviewed_video)}: {_safe_error_text(exc, 240)}")
                    st.session_state.pop(bulk_delete_key, None)
                    st.session_state.pop("_moments_reviewed_repick_index_v166", None)
                    if failures:
                        st.session_state["_moments_notice"] = f"確認済み動画を{deleted}本削除しました。{len(failures)}本は削除できませんでした。"
                        st.session_state["_moments_bulk_delete_error_detail"] = "\n".join(failures[:12])
                    else:
                        st.session_state["_moments_notice"] = f"確認済み動画{deleted}本を一斉削除しました。日記に残した写真はそのままです。"
                        st.session_state.pop("_moments_bulk_delete_error_detail", None)
                    reload_current_page_after_action()
            with cancel_col:
                if st.button(
                    "キャンセル",
                    use_container_width=True,
                    key="moments_delete_all_reviewed_no",
                ):
                    st.session_state.pop(bulk_delete_key, None)
                    st.rerun(scope="app")

        # v166: reviewed videos are intentionally mounted one at a time. The next
        # reviewed-video button lives inside the picker, directly below its three
        # candidate stills, so moving through old videos is a single smooth action.
        reviewed_index_key = "_moments_reviewed_repick_index_v166"
        try:
            reviewed_index = int(st.session_state.get(reviewed_index_key) or 0)
        except Exception:
            reviewed_index = 0
        reviewed_index = max(0, min(reviewed_index, len(reviewed) - 1))
        st.session_state[reviewed_index_key] = reviewed_index
        st.caption(f"{reviewed_index + 1} / {len(reviewed)}本目")
        next_cfg = None
        if len(reviewed) > 1:
            next_index = (reviewed_index + 1) % len(reviewed)
            next_cfg = {
                "state_key": reviewed_index_key,
                "next_index": next_index,
                "label": f"次の動画の写真へ →（{next_index + 1}/{len(reviewed)}）",
            }
        _render_moments_picker(
            reviewed[reviewed_index],
            1000 + reviewed_index,
            view_mode=view_mode,
            next_video_action=next_cfg,
        )



def render_diary_title_editor(trip_id, current_title, key_prefix):
    with st.expander("タイトルを変更"):
        edited_title = st.text_input(
            "日記タイトル",
            value=str(current_title or ""),
            key=f"{key_prefix}_title_input_{trip_id}",
        )
        if st.button(
            "タイトルを保存",
            use_container_width=True,
            key=f"{key_prefix}_title_save_{trip_id}",
        ):
            try:
                saved_title = update_diary_title(trip_id, edited_title)
                # Preserve the diary being viewed while the selectbox is rebuilt with
                # a fresh key, so its visible label changes immediately on mobile too.
                st.session_state.preferred_diary_trip_id = trip_id
                st.session_state["_diary_notice"] = f"日記のタイトルを「{saved_title}」に変更しました。"
                st.rerun()
            except Exception as exc:
                st.error("タイトルを変更できませんでした。")
                with st.expander("保護者向け詳細"):
                    st.code(str(exc))


@st.fragment
def render_recent_camera_photo_emotion(trip):
    """Show the latest saved media; still photos can be tagged by tapping the image."""
    trip_id = (trip or {}).get("id")
    if not trip_id:
        return
    recent_key = f"_camera_recent_photo_{trip_id}"
    photo_id = st.session_state.get(recent_key)
    if not photo_id:
        return

    photos = list_trip_photos(trip_id)
    photo = next((p for p in photos if p.get("id") == photo_id), None)
    if not photo:
        st.session_state.pop(recent_key, None)
        return

    st.divider()
    is_video = photo_is_video(photo)
    st.markdown("#### 今撮った動画" if is_video else "#### 今撮った写真")
    if is_video:
        if not render_saved_media_preview(
            photo,
            image_alt="今撮った動画の代表画像",
            delete_key_prefix="recent_camera",
        ):
            st.warning("撮影した動画のプレビューを表示できませんでした。")
        st.caption("✨ いい瞬間は動画保存とは別にバックグラウンドで作成します。切り取った写真は、日記画面でタップするたびに6つの気持ちを切り替えられます。")
        return

    location_label = photo_location_label(photo)
    st.caption("写真下の「通常／こどもーど」を切り替え、写真につけるアイコンを1つ選べます。")
    st.caption("モード切替・アイコン選択だけではページ更新しません。")

    path = str(photo.get("storage_path") or "")
    signed = signed_photo_url_map((path,)) if path else {}
    src = photo_display_url(photo, signed, max_px=720, quality=82)
    card = {
        "id": str(photo_id),
        "src": src,
        "emotion": photo_selected_tag_values(photo)[0],
        "parenting": photo_selected_tag_values(photo)[1],
        "location": str(location_label or ""),
    }
    gallery_component = _get_diary_gallery_component()
    if gallery_component is not None:
        serial_key = f"recent_emotion_serial_{photo_id}"
        serial = int(st.session_state.get(serial_key) or 0)
        result = gallery_component(
            data={"photos": [card], "single": True, "allow_delete": True, "allow_emotion": True, "mode_by_photo": st.session_state.get(f"_recent_icon_modes_{photo_id}") or {}, "family_key": current_family_key(), "member_key": current_member_key(), "pending_param": PENDING_EMOTION_QUERY_PARAM},
            key=f"recent_emotion_{photo_id}_{serial}_{_current_ui_refresh_epoch()}",
            on_delete_photo_id_change=lambda: None,
        )
        delete_clicked = str(getattr(result, "delete_photo_id", "") or "")
        if delete_clicked == str(photo_id):
            st.session_state[serial_key] = serial + 1
            confirm_photo_delete_dialog(
                trip_id,
                photo_id,
                photos=photos,
                is_pending=True,
                trip=trip,
            )
        return

    # Fallback for runtimes without Streamlit v2 components.
    if src:
        meta = photo_selected_tag_meta(photo)
        border = meta.get("color") or "#AEB6C2"
        emoji = meta.get("emoji") or ""
        badge = (
            f'<span style="position:absolute;right:10px;bottom:10px;background:rgba(255,255,255,.90);border-radius:999px;padding:3px 6px;font-size:22px;">{emoji}</span>'
            if emoji else ""
        )
        st.markdown(
            f'<div style="position:relative;padding:5px;border:3px solid {border};border-radius:14px;max-width:360px;margin:0 auto;">'
            f'<img src="{html.escape(src, quote=True)}" style="display:block;width:100%;aspect-ratio:1/1;object-fit:cover;border-radius:9px;" />{badge}</div>',
            unsafe_allow_html=True,
        )
    if st.button("写真の気持ちを次へ", use_container_width=True, key=f"recent_emotion_fallback_{photo_id}"):
        update_photo_emotion(photo_id, next_photo_emotion_key(photo_emotion_key(photo)), trip_id=trip_id)
        st.rerun()


# ============================================================
# Page: Trip / camera
# ============================================================
def page_trip():
    if st.button("←", key="camera_back_parent", help="1つ前の階層に戻る"):
        navigate_to_parent()

    notice = st.session_state.pop("_camera_notice", None)
    if notice:
        st.success(notice)

    if live_camera_component is None:
        st.error("ライブカメラ機能に必要なStreamlitのバージョンが古いです。requirements.txtを更新してください。")
        return

    # Video mode is gated before recording begins. Capacity and Storage-upload
    # preparation are deliberately reported as separate states: a failure to mint
    # an upload destination must never be mislabeled as "capacity shortage".
    video_unavailable_reason = ""
    try:
        video_capacity = video_recording_capacity_status()
    except Exception as exc:
        video_capacity = {
            "allowed": False,
            "message": "動画の保存容量を確認できないため、動画撮影を一時停止しています。",
        }
        video_unavailable_reason = "capacity_check"
        with st.expander("動画容量チェックの詳細"):
            st.code(str(exc))

    if not bool(video_capacity.get("allowed")):
        if not video_unavailable_reason:
            video_unavailable_reason = "quota"
        st.warning(str(video_capacity.get("message") or "動画の保存容量が不足しています。"))

    auto_start = bool(st.session_state.pop("_camera_auto_start", False))
    auto_start_video = bool(st.session_state.pop("_camera_auto_start_video", False))
    active_snapshot = st.session_state.get("_active_trip_snapshot")
    if not isinstance(active_snapshot, dict) or active_snapshot.get("trip_date") != today_iso() or active_snapshot.get("status") != "active":
        active_snapshot = None

    # v107: reserve a short-lived signed Storage upload destination before video
    # recording. The browser can then PUT the Blob straight to Supabase and only
    # return compact metadata to Streamlit.
    video_reservation = {}
    video_allowed = bool(video_capacity.get("allowed"))
    video_capacity_message = str(video_capacity.get("message") or "")
    camera_trip = active_snapshot
    if video_allowed:
        try:
            camera_trip = camera_trip or ensure_today_trip()
            video_reservation = get_camera_video_upload_reservation(
                camera_trip["id"],
                st.session_state.capture_serial,
            )
        except Exception as exc:
            video_allowed = False
            video_unavailable_reason = "storage_setup"
            video_capacity_message = "保存容量ではなく、動画のアップロード先を準備できないため撮影を開始できません。"
            st.error(video_capacity_message)
            st.caption(f"Supabaseキー：{_supabase_secret_key_kind()} / Bucket：{PHOTO_BUCKET}")
            with st.expander("動画保存先の準備エラー", expanded=True):
                st.code(_safe_error_text(exc, 900))

    camera_trip_key = str((camera_trip or {}).get("id") or "pending")
    browser_video_max_bytes = VIDEO_MAX_BYTES
    remaining_for_recording = video_capacity.get("remaining_bytes")
    if remaining_for_recording is not None:
        try:
            browser_video_max_bytes = min(VIDEO_MAX_BYTES, max(0, int(remaining_for_recording)))
        except Exception:
            browser_video_max_bytes = VIDEO_MAX_BYTES
    result = live_camera_component(
        data={
            "auto_start": auto_start,
            "auto_start_mode": "video" if auto_start_video else ("photo" if auto_start else ""),
            "video_allowed": video_allowed,
            "video_capacity_message": video_capacity_message,
            "video_unavailable_reason": video_unavailable_reason,
            "video_max_bytes": browser_video_max_bytes,
            "video_upload_signed_url": str(video_reservation.get("signed_url") or ""),
            "video_upload_storage_path": str(video_reservation.get("storage_path") or ""),
            "video_candidate_sheet_signed_url": str(video_reservation.get("candidate_sheet_signed_url") or ""),
            "video_candidate_sheet_storage_path": str(video_reservation.get("candidate_sheet_path") or ""),
        },
        key=f"live_camera_v155_{camera_trip_key}_{st.session_state.capture_serial}_{_current_ui_refresh_epoch()}",
        on_photo_change=lambda: None,
        on_video_change=lambda: None,
        on_camera_error_change=lambda: None,
    )

    payload = getattr(result, "photo", None)
    video_payload = getattr(result, "video", None)
    camera_error = getattr(result, "camera_error", None)

    if camera_error:
        message = camera_error.get("message") if isinstance(camera_error, dict) else str(camera_error)
        if message:
            st.warning(message)
        if isinstance(camera_error, dict):
            detail = str(camera_error.get("detail") or "").strip()
            if detail and detail not in str(message or ""):
                with st.expander("動画保存エラーの詳細", expanded=True):
                    st.code(detail)

    if (
        isinstance(video_payload, dict)
        and video_payload.get("upload_complete")
        and video_payload.get("video_storage_path")
    ):
        save_stage = "アップロード済み動画の確認"
        video_saved = False
        uploaded_video_path = str(video_payload.get("video_storage_path") or "").strip()
        try:
            reservation = st.session_state.get("_camera_video_upload_reservation_v116")
            if not isinstance(reservation, dict):
                raise ValueError("動画の保存予約を確認できませんでした。")
            reserved_video_path = str(reservation.get("storage_path") or "").strip()
            if uploaded_video_path != reserved_video_path:
                # A Streamlit rerun can recreate the reservation object while the browser
                # is finishing a direct upload. The uploaded path itself was originally
                # minted by this server, so accept it when it is still inside the current
                # signed-in member and trip prefix. This also makes registration resilient
                # to a stale reservation without weakening cross-member isolation.
                safe_prefix = (
                    f"{current_family_key()}/{current_member_key()}/"
                    f"{str(reservation.get('trip_id') or '')}/"
                )
                if not (
                    uploaded_video_path.startswith(safe_prefix)
                    and _storage_path_is_original_video(
                        uploaded_video_path,
                        video_payload.get("mime_type"),
                    )
                ):
                    raise ValueError("動画の保存先が撮影前の予約と一致しません。")

            save_stage = "代表画像の読み込み"
            poster_raw = b""
            try:
                poster_raw = decode_camera_data_url(video_payload.get("poster_data_url"))
            except Exception:
                # The original video is already safely in Storage. If the compact
                # poster value was dropped by the component runtime, reuse the first
                # valid AI still rather than failing the whole video registration.
                for frame_item in video_payload.get("candidate_frames") or []:
                    if not isinstance(frame_item, dict):
                        continue
                    try:
                        poster_raw = decode_camera_data_url(frame_item.get("data_url"))
                    except Exception:
                        poster_raw = b""
                    if poster_raw:
                        break
                # A missing poster must not invalidate an already-uploaded original.
                # register_browser_uploaded_video() creates a neutral placeholder.

            video_size = max(0, int(video_payload.get("video_size_bytes") or 0))
            recording_id = str(video_payload.get("recording_id") or "").strip()
            digest_source = f"{uploaded_video_path}|{video_size}|{recording_id}"
            digest = hashlib.sha1(digest_source.encode("utf-8")).hexdigest()
            digest_key = "saved_camera_video_digest_current"
            if st.session_state.get(digest_key) != digest:
                save_stage = "動画記録の登録"
                trip = ensure_today_trip()
                if str(trip.get("id") or "") != str(reservation.get("trip_id") or ""):
                    raise ValueError("動画の保存先と現在のぶらり旅が一致しません。")
                capture_source = str(video_payload.get("source") or "video_camera")
                location = build_photo_location(
                    video_payload.get("location"),
                    trip,
                    capture_source=capture_source,
                )

                with st.spinner("動画を保管庫に登録しています…"):
                    saved_video = register_browser_uploaded_video(
                        trip["id"],
                        uploaded_video_path,
                        video_size,
                        poster_raw,
                        mime_type=video_payload.get("mime_type"),
                        duration_ms=video_payload.get("duration_ms"),
                        location=location,
                        captured_at=video_payload.get("captured_at"),
                        capture_source=capture_source,
                        capture_width=video_payload.get("capture_width"),
                        capture_height=video_payload.get("capture_height"),
                        capture_frame_rate=video_payload.get("capture_frame_rate"),
                        video_bitrate_bps=video_payload.get("video_bitrate_bps"),
                    )

                video_saved = True
                st.session_state[digest_key] = digest
                if isinstance(saved_video, dict) and saved_video.get("id"):
                    st.session_state[f"_camera_recent_photo_{trip['id']}"] = saved_video["id"]
                try:
                    _home_video_counts_cached.clear()
                except Exception:
                    pass

                # Legacy compatibility: prefer a browser contact sheet when one exists in
                # the browser while/just after recording. This makes ffmpeg optional.
                ai_status = "queued_recovery"
                if isinstance(saved_video, dict) and saved_video.get("id"):
                    sheet_path = str(video_payload.get("candidate_sheet_path") or "").strip()
                    sheet_manifest = [x for x in (video_payload.get("candidate_manifest") or []) if isinstance(x, dict)]
                    reserved_sheet = str(reservation.get("candidate_sheet_path") or "").strip()
                    if sheet_path and reserved_sheet and sheet_path == reserved_sheet and sheet_manifest:
                        try:
                            saved_video = store_video_ai_candidate_sheet(
                                saved_video,
                                sheet_path,
                                sheet_manifest,
                                columns=video_payload.get("candidate_sheet_columns") or 15,
                                rows=video_payload.get("candidate_sheet_rows") or 0,
                            )
                            ai_status = "queued"
                        except Exception:
                            ai_status = "queued_recovery"
                    if ai_status == "queued_recovery":
                        try:
                            saved_video = mark_video_ai_waiting_candidates(
                                saved_video,
                                "ブラウザ候補を確認できないため、自動復旧を準備しています。",
                            )
                        except Exception:
                            pass

                if ai_status in {"queued", "queued_recovery"} and isinstance(saved_video, dict) and saved_video.get("id"):
                    # The original video is already committed. Queue Good Moments and
                    # immediately return control to the camera/UI; never wait here.
                    try:
                        launch_video_ai_background_job(saved_video)
                    except Exception as background_exc:
                        ai_status = "queued_recovery"
                        try:
                            reflection = dict(photo_media_metadata(saved_video))
                            selection = reflection.get("ai_selection") or {}
                            if not isinstance(selection, dict):
                                selection = {}
                            selection["status"] = "waiting_candidates"
                            selection["stage"] = "candidate_preparation"
                            selection["last_error"] = str(background_exc)[:240]
                            selection["updated_at"] = now_jst().isoformat()
                            selection["pipeline_mode"] = "background_single_pass_dynamic20_v153"
                            reflection["ai_selection"] = selection
                            _write_photo_reflection(saved_video["id"], reflection)
                        except Exception:
                            pass

                previous_count = st.session_state.get("_home_today_photo_count")
                try:
                    previous_count = int(previous_count) if previous_count is not None else 0
                except Exception:
                    previous_count = 0
                st.session_state["_home_today_photo_count"] = previous_count + 1
                place_label = str((location or {}).get("place_label") or trip.get("destination") or "").strip()
                if place_label:
                    st.session_state["_home_today_place"] = place_label

                clear_camera_video_upload_reservation()
                st.session_state["_browser_last_camera_open_at"] = time.time() * 1000.0
                st.session_state["_browser_last_camera_mode"] = "video"
                st.session_state.capture_serial += 1
                if ai_status in {"queued", "queued_recovery"}:
                    notice = "動画を保管庫に保存しました。いい瞬間はバックグラウンドで作成します。操作を続けられます。"
                else:
                    notice = "動画を保管庫に保存しました。いい瞬間を自動で作成しました。"
                st.session_state["_camera_notice"] = notice
                reload_current_page_after_action()
        except Exception as exc:
            if video_saved:
                st.warning("動画本体は保管庫に保存済みです。保存後の処理だけ完了できませんでした。")
            else:
                detail = str(exc).strip().replace("\n", " ")
                if len(detail) > 220:
                    detail = detail[:217] + "..."
                st.error(f"動画を保存できませんでした。処理段階：{save_stage}" + (f" ／ {detail}" if detail else ""))
                # The Blob was already uploaded directly by the browser. Remove it if
                # registration failed, so the next recording can safely reuse the same
                # signed reservation without leaving an orphaned object.
                if uploaded_video_path:
                    try:
                        cleanup_trip_id = str(
                            (reservation.get("trip_id") if isinstance(reservation if 'reservation' in locals() else None, dict) else None)
                            or (camera_trip or {}).get("id")
                            or ""
                        )
                        cleanup_prefix = f"{current_family_key()}/{current_member_key()}/{cleanup_trip_id}/"
                        if (
                            cleanup_trip_id
                            and uploaded_video_path.startswith(cleanup_prefix)
                            and _storage_path_is_original_video(
                                uploaded_video_path,
                                video_payload.get("mime_type"),
                            )
                        ):
                            supabase_client().storage.from_(PHOTO_BUCKET).remove([uploaded_video_path])
                            _invalidate_video_storage_audit_cache()
                    except Exception:
                        pass
            with st.expander("保護者向け詳細"):
                st.code(f"処理段階: {save_stage}\n{exc}")

    if isinstance(payload, dict) and payload.get("data_url"):
        try:
            raw = decode_camera_data_url(payload["data_url"])
            digest = hashlib.sha1(raw).hexdigest()
            digest_key = "saved_camera_digest_current"
            if st.session_state.get(digest_key) != digest:
                trip = ensure_today_trip()
                capture_source = str(payload.get("source") or "camera")
                location = build_photo_location(
                    payload.get("location"),
                    trip,
                    capture_source=capture_source,
                )

                initial_emotion = normalize_photo_emotion_key(payload.get("emotion"))
                initial_parenting = normalize_parenting_tag_key(payload.get("parenting"))
                if initial_emotion and initial_parenting:
                    # v168 clients send only one; stale clients are normalized to one as well.
                    initial_parenting = ""
                extra_reflection = {}
                if initial_emotion:
                    extra_reflection["emotion"] = photo_emotion_record(
                        initial_emotion,
                        source="child_tap_camera_review_v162",
                    )
                if initial_parenting:
                    extra_reflection["parenting_tag"] = parenting_tag_record(
                        initial_parenting,
                        source="parent_tap_camera_review_v162",
                    )
                if not extra_reflection:
                    extra_reflection = None

                with st.spinner("写真を残しています…"):
                    saved_photo = upload_photo(
                        trip["id"],
                        raw,
                        location=location,
                        captured_at=payload.get("captured_at"),
                        capture_source=capture_source,
                        extra_reflection=extra_reflection,
                    )

                st.session_state[digest_key] = digest
                if isinstance(saved_photo, dict) and saved_photo.get("id"):
                    st.session_state[f"_camera_recent_photo_{trip['id']}"] = saved_photo["id"]

                previous_count = st.session_state.get("_home_today_photo_count")
                try:
                    previous_count = int(previous_count) if previous_count is not None else 0
                except Exception:
                    previous_count = 0
                st.session_state["_home_today_photo_count"] = previous_count + 1
                place_label = str((location or {}).get("place_label") or trip.get("destination") or "").strip()
                if place_label:
                    st.session_state["_home_today_place"] = place_label

                st.session_state["_browser_last_camera_open_at"] = time.time() * 1000.0
                st.session_state["_browser_last_camera_mode"] = "photo"
                st.session_state.capture_serial += 1
                st.session_state["_camera_notice"] = "写真を保存しました。"
                reload_current_page_after_action()
        except Exception as exc:
            st.error("写真を保存できませんでした。")
            with st.expander("保護者向け詳細"):
                st.code(str(exc))

    trip = st.session_state.get("_active_trip_snapshot")
    if isinstance(trip, dict) and trip.get("id"):
        render_recent_camera_photo_emotion(trip)


@st.fragment
def render_diary_emotion_gallery(trip_id, photos, trip=None, is_pending=False):
    """Render still photos with emotion editing and an optional saved-diary viewer mode."""
    photos = diary_photos_only(photos)
    if not photos:
        return
    st.markdown("#### この日の写真")
    counts, selected = photo_emotion_counts(photos)
    st.caption("写真下の「通常／こどもーど」を切り替え、写真につけるアイコンを1つ選べます。")
    summary = photo_emotion_summary_text(photos)
    st.caption(f"感情選択済み：{selected} / {len(photos)}枚" + (f"　｜　{summary}" if summary else ""))

    # v179: saved diary days can be viewed either as the familiar three-column grid
    # or one photo at a time. Pending diary photos stay in the editing-first grid.
    view_mode = "3列一覧"
    if not is_pending and len(photos) > 1:
        view_mode = st.radio(
            "写真の表示モード",
            ["3列一覧", "1枚ずつ拡大"],
            horizontal=True,
            key=f"diary_saved_photo_view_mode_{trip_id}",
            label_visibility="collapsed",
        )

    # v180: enlarged mode keeps all photos in one browser component. The component
    # swaps the visible card locally and preloads neighboring images, avoiding a rerun
    # for every Previous/Next tap.
    displayed_photos = photos
    paths = tuple(str(photo.get("storage_path") or "") for photo in displayed_photos if photo.get("storage_path"))
    signed = signed_photo_url_map(paths) if paths else {}
    cards = []
    photo_ids = []
    for photo in displayed_photos:
        pid = str(photo.get("id") or "")
        if not pid:
            continue
        cards.append(
            {
                "id": pid,
                "src": photo_display_url(photo, signed, max_px=1400 if view_mode == "1枚ずつ拡大" else 520, quality=90 if view_mode == "1枚ずつ拡大" else 80),
                "emotion": photo_selected_tag_values(photo)[0],
                "parenting": photo_selected_tag_values(photo)[1],
                "location": str(photo_location_label(photo) or ""),
                "tags": photo_ai_tags(photo)[:12],
            }
        )
        photo_ids.append(pid)

    gallery_component = _get_diary_gallery_component()
    if gallery_component is not None and cards:
        serial_key = f"diary_emotion_gallery_serial_{trip_id}_{'pending' if is_pending else 'saved'}"
        serial = int(st.session_state.get(serial_key) or 0)
        result = gallery_component(
            data={"photos": cards, "single": view_mode == "1枚ずつ拡大", "allow_delete": True, "allow_emotion": True, "carousel_key": f"diary_saved_{trip_id}", "mode_by_photo": st.session_state.get(f"_diary_icon_modes_{trip_id}") or {}, "family_key": current_family_key(), "member_key": current_member_key(), "pending_param": PENDING_EMOTION_QUERY_PARAM},
            key=f"diary_emotion_gallery_{trip_id}_{serial}_{_current_ui_refresh_epoch()}_{'large' if view_mode == '1枚ずつ拡大' else 'grid'}_v180",
            on_delete_photo_id_change=lambda: None,
        )
        delete_clicked = str(getattr(result, "delete_photo_id", "") or "")
        if delete_clicked in photo_ids:
            st.session_state[serial_key] = serial + 1
            confirm_photo_delete_dialog(
                trip_id,
                delete_clicked,
                photos=photos,
                is_pending=is_pending,
                trip=trip,
            )
        return

    # Fallback for old component runtimes.
    fallback_displayed = displayed_photos
    if view_mode == "1枚ずつ拡大" and displayed_photos:
        fallback_index_key = f"diary_saved_photo_enlarged_index_{trip_id}"
        try:
            fallback_index = int(st.session_state.get(fallback_index_key) or 0)
        except Exception:
            fallback_index = 0
        fallback_index = max(0, min(fallback_index, len(displayed_photos) - 1))
        prev_col, count_col, next_col = st.columns([1, 1.25, 1], gap="small")
        with prev_col:
            if st.button("◀ 前へ", use_container_width=True, disabled=fallback_index <= 0, key=f"diary_saved_photo_prev_{trip_id}"):
                st.session_state[fallback_index_key] = max(0, fallback_index - 1)
                st.rerun()
        with count_col:
            st.markdown(f'<div style="text-align:center;padding:.55rem .2rem;font-weight:800;">{fallback_index + 1} / {len(displayed_photos)}</div>', unsafe_allow_html=True)
        with next_col:
            if st.button("次へ ▶", use_container_width=True, disabled=fallback_index >= len(displayed_photos) - 1, key=f"diary_saved_photo_next_{trip_id}"):
                st.session_state[fallback_index_key] = min(len(displayed_photos) - 1, fallback_index + 1)
                st.rerun()
        fallback_displayed = [displayed_photos[fallback_index]]
    fallback_columns = 1 if view_mode == "1枚ずつ拡大" else 3
    cols = st.columns(fallback_columns, gap="small")
    for index, photo in enumerate(fallback_displayed):
        with cols[index % fallback_columns]:
            src = photo_display_url(photo, signed, max_px=1400 if view_mode == "1枚ずつ拡大" else 420, quality=90 if view_mode == "1枚ずつ拡大" else 76)
            meta = photo_selected_tag_meta(photo)
            border = meta.get("color") or "#AEB6C2"
            emoji = meta.get("emoji") or ""
            if src:
                badge = (
                    f'<span style="position:absolute;right:7px;bottom:7px;background:rgba(255,255,255,.90);border-radius:999px;padding:2px 5px;font-size:19px;">{emoji}</span>'
                    if emoji else ""
                )
                image_style = "display:block;width:100%;max-height:68vh;object-fit:contain;border-radius:8px;" if view_mode == "1枚ずつ拡大" else "display:block;width:100%;aspect-ratio:1/1;object-fit:cover;border-radius:8px;"
                st.markdown(
                    f'<div style="position:relative;padding:4px;border:3px solid {border};border-radius:12px;">'
                    f'<img src="{html.escape(src, quote=True)}" loading="lazy" decoding="async" style="{image_style}" />{badge}</div>',
                    unsafe_allow_html=True,
                )
            if st.button(
                "気持ちを次へ",
                use_container_width=True,
                key=f"emotion_fallback_{trip_id}_{photo.get('id')}_{'pending' if is_pending else 'saved'}_{'large' if view_mode == '1枚ずつ拡大' else 'grid'}",
            ):
                update_photo_emotion(
                    photo.get("id"),
                    next_photo_emotion_key(photo_emotion_key(photo)),
                    trip_id=trip_id,
                )
                st.rerun()
            if st.button(
                "×",
                key=f"diary_emotion_delete_{trip_id}_{photo.get('id')}_{'pending' if is_pending else 'saved'}_{'large' if view_mode == '1枚ずつ拡大' else 'grid'}",
                help="この写真を削除",
            ):
                confirm_photo_delete_dialog(
                    trip_id,
                    photo.get("id"),
                    photos=photos,
                    is_pending=is_pending,
                    trip=trip,
                )


# ============================================================
# Page: Diary (photo emotion tagging)
# ============================================================
def page_diary():
    # Remove transient state from the retired comment/conversation UI. Historical
    # data stays in Supabase for compatibility, but v149 never asks for comments.
    st.session_state.pop("_pending_diary_open_trip_id", None)
    for key in list(st.session_state.keys()):
        key_text = str(key)
        if key_text.startswith("diary_talk_photo_") or key_text.startswith("diary_selected_photo_") or key_text.startswith("reflection_state_"):
            st.session_state.pop(key, None)

    page_top(
        "📖 日記",
        "写真をタップするたびに6つの気持ちを切り替え、その記録から日記を作ります。気持ちを変えるだけではページ更新しません。コメント入力は使いません。",
    )
    notice = st.session_state.pop("_diary_notice", None)
    if notice:
        st.success(notice)
    render_photo_tag_notices()

    recent_rows = list_recent_diaries(limit=80)
    saved_titles = [
        str((row.get("diary") or {}).get("title") or "").strip()
        for row in recent_rows
        if str((row.get("diary") or {}).get("title") or "").strip()
    ]
    pending_rows = list_pending_photo_trips()

    if pending_rows:
        st.markdown("#### まだ日記になっていない写真")
        st.caption("写真をタップするたびに 未設定 → 🥰 ほっこりした → 😊 うれしい → 😲 びっくり → 😠 おこった → 😢 かなしい → 😣 くやしい → 未設定 の順で変わります。気持ちを変えるだけではページ更新せず、次に別の操作をしたときにまとめて保存します。")
        pending_titles = pending_diary_titles(pending_rows, used_titles=saved_titles)
        for item in pending_rows:
            pending_trip = item.get("trip") or {}
            pending_photos = diary_photos_only(item.get("photos") or [])
            pending_id = str(pending_trip.get("id") or "")
            if not pending_id or not pending_photos:
                continue
            pending_title = pending_titles.get(pending_id) or diary_title_for_trip(pending_trip, pending_photos)
            emotion_counts, emotion_selected = photo_emotion_counts(pending_photos)
            st.markdown(
                f"**{html.escape(str(pending_trip.get('trip_date') or ''))}　{html.escape(pending_title)}**　・ 写真 {len(pending_photos)}枚"
            )
            st.caption(f"感情選択済み：{emotion_selected} / {len(pending_photos)}枚" + (f"　｜　{photo_emotion_summary_text(pending_photos)}" if photo_emotion_summary_text(pending_photos) else ""))
            render_diary_emotion_gallery(
                pending_id,
                pending_photos,
                trip=pending_trip,
                is_pending=True,
            )
            if st.button(
                "📖 この写真で日記を作る",
                type="primary",
                use_container_width=True,
                key=f"create_pending_diary_{pending_id}",
            ):
                try:
                    with st.spinner("未タグ写真にはAIタグを付けて、日記を保存しています…"):
                        create_and_save_diary_from_photos(
                            pending_trip,
                            pending_photos,
                            requested_title=pending_title,
                            reason="diary_page_pending_button_v149",
                        )
                    if st.session_state.get("active_trip_id") == pending_id:
                        st.session_state.active_trip_id = None
                        _invalidate_active_trip_snapshot()
                    st.session_state.preferred_diary_trip_id = pending_id
                    st.session_state["_diary_notice"] = "日記を作成して保存しました。"
                    st.rerun()
                except Exception as exc:
                    st.error("日記を作成できませんでした。")
                    with st.expander("保護者向け詳細"):
                        st.code(str(exc))
            st.divider()

    diary_map = {
        str((row.get("diary") or {}).get("trip_id") or ""): row.get("diary") or {}
        for row in recent_rows
        if (row.get("diary") or {}).get("trip_id")
    }
    trips = [row.get("trip") or {} for row in recent_rows if (row.get("trip") or {}).get("id")]
    if not trips:
        if not pending_rows:
            st.info("まだ日記はありません。")
        return

    ids = [str(t["id"]) for t in trips]
    trip_map = {str(t["id"]): t for t in trips}
    label_map = {
        trip_id_value: f"{trip_map[trip_id_value].get('trip_date', '')}　"
        f"{diary_display_title(diary_map.get(trip_id_value), trip_map[trip_id_value], photos=None)}"
        for trip_id_value in ids
    }
    preferred = st.session_state.preferred_diary_trip_id
    default_index = ids.index(str(preferred)) if str(preferred) in ids else None
    selector_serial = int(st.session_state.get("_diary_selector_serial") or 0)
    trip_id = st.selectbox(
        "振り返る日",
        ids,
        index=default_index,
        placeholder="振り返る日を選んでください",
        format_func=lambda x: label_map.get(str(x), str(x)),
        key=f"diary_trip_selector_{selector_serial}",
    )
    if trip_id is None:
        st.caption("振り返る日を選ぶと、そのぶらり旅の日記と写真を表示します。")
        return

    trip_id = str(trip_id)
    trip = trip_map[trip_id]
    photos = diary_photos_only(list_trip_photos(trip_id))
    existing = diary_map.get(trip_id)

    if photos:
        render_ai_photo_tag_action(
            photos,
            key=f"diary_day_{trip_id}",
            scope_label="この日の写真",
        )
        render_diary_emotion_gallery(trip_id, photos, trip=trip, is_pending=False)
    else:
        st.warning("このぶらり旅には写真がありません。")

    if not existing:
        if photos and st.button(
            "📖 この写真で日記を作る",
            type="primary",
            use_container_width=True,
            key=f"create_selected_diary_{trip_id}",
        ):
            try:
                with st.spinner("未タグ写真にはAIタグを付けて、日記を保存しています…"):
                    create_and_save_diary_from_photos(
                        trip,
                        photos,
                        reason="diary_selected_trip_v149",
                    )
                st.session_state.preferred_diary_trip_id = trip_id
                st.session_state["_diary_notice"] = "日記を作成して保存しました。"
                st.rerun()
            except Exception as exc:
                st.error("日記を作成できませんでした。")
                with st.expander("保護者向け詳細"):
                    st.code(str(exc))
        render_diary_delete_controls(trip_id, photos)
        return

    existing_title = diary_display_title(existing, trip, photos=photos)
    st.markdown(
        f"""
        <div class="diary-card">
          <div class="hero-title">{html.escape(existing_title)}</div>
          <div class="big-text">{html.escape(existing.get('diary_text') or '')}</div>
        </div>
        """,
        unsafe_allow_html=True,
    )
    existing_meta = existing.get("ai_meta") or {}

    if photos and st.button(
        "AIにまとめてもらう",
        use_container_width=True,
        key=f"ai_trip_summary_{trip_id}",
    ):
        try:
            with st.spinner("写真と選んだ気持ちを見て、このぶらり旅をまとめています…"):
                summary_result = summarize_burari_from_photos(trip, photos)
                save_burari_ai_summary(trip_id, summary_result)
            st.session_state["_diary_notice"] = "写真と選んだ気持ちからAIのまとめを更新しました。"
            st.rerun()
        except Exception as exc:
            st.error("AIのまとめを作れませんでした。もう一度試してください。")
            with st.expander("保護者向け詳細"):
                st.code(str(exc))

    render_burari_trip_summary(existing_meta)
    render_diary_reflection_summary(existing_meta)
    render_summary_feedback_controls(existing_meta, trip_id, "saved")
    render_diary_title_editor(trip_id, existing_title, "diary_existing")

    if photos and st.button(
        "この日の写真と選んだ気持ちから、日記を作り直す",
        use_container_width=True,
        key=f"recreate_diary_from_emotions_{trip_id}",
    ):
        try:
            with st.spinner("未タグ写真を確認して、日記を作り直しています…"):
                create_and_save_diary_from_photos(
                    trip,
                    photos,
                    requested_title=existing_title,
                    reason="diary_recreate_emotions_v149",
                )
            st.session_state.preferred_diary_trip_id = trip_id
            st.session_state["_diary_notice"] = "写真の気持ちをもとに日記を作り直しました。"
            st.rerun()
        except Exception as exc:
            st.error("日記を作り直せませんでした。")
            with st.expander("保護者向け詳細"):
                st.code(str(exc))

    render_diary_delete_controls(trip_id, photos)
    return


def page_history(embedded=False):
    if not embedded:
        page_top("📚 これまでの日記")

    notice = st.session_state.pop("_diary_notice", None)
    if notice:
        st.success(notice)
    render_photo_tag_notices()

    rows = list_recent_diaries()
    if not st.session_state.get("history_detail_trip_id"):
        try:
            all_tag_photos = list_member_still_photos_for_tags()
            render_ai_photo_tag_action(
                all_tag_photos,
                key="history_all_photos",
                scope_label="これまでの写真",
            )
            render_photo_tag_browser(all_tag_photos, key="history_all_photos")
        except Exception as exc:
            with st.expander("写真タグ機能の詳細"):
                st.code(str(exc))

    if not rows:
        st.session_state.pop("history_detail_trip_id", None)
        st.info("まだ日記はありません。")
        return

    detail_trip_id = st.session_state.get("history_detail_trip_id")
    detail_row = next(
        (row for row in rows if row.get("diary", {}).get("trip_id") == detail_trip_id),
        None,
    )
    if detail_trip_id and detail_row is None:
        st.session_state.pop("history_detail_trip_id", None)
        detail_trip_id = None

    # A diary title opens a dedicated detail screen. This makes the bottom
    # navigation unambiguous on a phone: back returns to the history list.
    if detail_row is not None:
        diary = detail_row["diary"]
        trip = detail_row["trip"]
        trip_id = diary["trip_id"]
        photos = diary_photos_only(list_trip_photos(trip_id))
        daily_title = diary_display_title(diary, trip, photos=photos)
        title = f"{trip.get('trip_date', '')}　{daily_title}"

        st.markdown(f"### {html.escape(title)}")
        render_diary_title_editor(trip_id, daily_title, "history_detail")
        render_history_photo_viewer(photos, trip_id)
        st.markdown(
            f"""
            <div class="diary-card">
              <div class="big-text">{html.escape(diary.get('diary_text') or '')}</div>
            </div>
            """,
            unsafe_allow_html=True,
        )

        meta = diary.get("ai_meta") or {}
        render_burari_trip_summary(meta)
        render_diary_reflection_summary(meta)
        render_summary_feedback_controls(meta, trip_id, "history")
        emotion_points = meta.get("emotion_points", []) if isinstance(meta, dict) else []
        if emotion_points:
            with st.expander("この振り返りのもとになった気持ち"):
                for point in emotion_points[:4]:
                    st.write("・" + str(point))
        else:
            # Older diaries may still contain pre-v149 comment evidence. Keep it
            # readable for historical compatibility, but new input is emotion-only.
            child_points = meta.get("child_points", []) if isinstance(meta, dict) else []
            if child_points:
                with st.expander("以前のコメント記録"):
                    for point in child_points[:3]:
                        st.write("・" + str(point))

        st.divider()
        back_col, home_col = st.columns(2)
        with back_col:
            with st.container(key="history_back_nav"):
                if st.button(
                    "← 前の画面に戻る",
                    use_container_width=True,
                    key=f"history_back_{trip_id}",
                ):
                    st.session_state.pop("history_detail_trip_id", None)
                    st.rerun()
        with home_col:
            with st.container(key="history_home_nav"):
                if st.button(
                    "トップ画面に戻る",
                    use_container_width=True,
                    key=f"history_home_{trip_id}",
                ):
                    st.session_state.pop("history_detail_trip_id", None)
                    go_page("home")

        if st.button(
            "🗑 この日記を削除",
            use_container_width=True,
            key=f"history_delete_{trip_id}",
        ):
            confirm_diary_delete_dialog(trip_id, len(photos))
        return

    st.caption("読みたい日記を選んでください。")
    for row in rows:
        diary = row["diary"]
        trip = row["trip"]
        trip_id = diary["trip_id"]
        # Saved diaries already carry their final title. Avoid one photo query per row.
        daily_title = diary_display_title(diary, trip, photos=None)
        title = f"{trip.get('trip_date', '')}　{daily_title}"
        if st.button(
            title,
            use_container_width=True,
            key=f"history_open_{trip_id}",
        ):
            st.session_state["history_detail_trip_id"] = trip_id
            st.rerun()


def render_monthly_ai_comments(review):
    review = review if isinstance(review, dict) else {}
    st.markdown("#### AIからの気づき")
    opening = str(review.get("opening") or "").strip()
    if opening:
        st.markdown(
            f'<div class="monthly-card"><div class="big-text">{html.escape(opening)}</div></div>',
            unsafe_allow_html=True,
        )

    first_question = ""
    for finding in list(review.get("findings", []) or [])[:2]:
        if not isinstance(finding, dict):
            continue
        theme = str(finding.get("theme") or "").strip()
        insight = str(finding.get("evidence") or "").strip()
        if theme:
            st.markdown(f"**{theme}**")
        if insight:
            st.write(insight)
        if not first_question:
            first_question = str(finding.get("ask_child") or "").strip()

    question = first_question or str(review.get("one_question") or "").strip()
    if question:
        st.info(f"ちょっと考えてみる：{question}")

    with st.expander("保護者向けメモ"):
        st.write(review.get("parent_note", ""))
        review_scope_type = str(review.get("_review_scope_type") or "")
        if review_scope_type == "ai_tag":
            tag_display = str(review.get("_tag_label") or review.get("_ai_tag_key") or "選んだAIタグ")
            st.caption(
                f"AIが写真から見える内容を整理した『{tag_display}』タグの写真を、日付・枚数など確認できる範囲で振り返っています。"
                "人物関係・性格・能力などは推測しません。"
            )
        elif review_scope_type == "tag":
            tag_display = str(review.get("_tag_label") or "選んだタグ")
            st.caption(
                f"写真に付けた『{tag_display}』タグの記録を、日付・枚数など確認できる事実の範囲で振り返っています。"
                "性格診断・能力評価・将来予測ではありません。"
            )
        else:
            st.caption(
                "本人が写真ごとに選んだ気持ちの傾向を、断定しすぎない範囲で振り返っています。"
                "性格診断・能力評価・将来予測ではありません。"
            )


